/**
 * External dependencies
 */
import classnames from 'classnames';

// css-1xm74da was generated by emotion and is part of saved markup, so it must stay.
const EMOTION_CLASS = 'css-1xm74da';

function Icon( props ) {
	const { attributes } = props;
	const { icon, iconColor, iconSize, altText } = attributes;

	return (
		<i
			className={ classnames(
				'yard-blocks-iconlist__icon',
				EMOTION_CLASS,
				icon
			) }
			style={ { color: iconColor, fontSize: iconSize } }
			title={ altText ? altText : null }
		></i>
	);
}

export default Icon;
